old='''	var c := Matter.card(Impact.stone_id(rock_kind))
	var chi := CHI * sqrt(float(c.young) * 1e9 / float(c.h))
	return pow(chi * force / (float(c.kic) * 1e6), 2.0 / 3.0)'''
new='''	var c := Matter.card(Impact.stone_id(rock_kind))
	if not c.has("kic"):                 # (W2 cards: R and the modulus only; K_Ic = sqrt(R E / PROCESS), Matter.r's inverse)
		var em := float(c.e_mod)
		return pow(CHI * sqrt(em / float(c.h)) * force / sqrt(float(c.r) * em / Matter.PROCESS), 2.0 / 3.0)
	var chi := CHI * sqrt(float(c.young) * 1e9 / float(c.h))
	return pow(chi * force / (float(c.kic) * 1e6), 2.0 / 3.0)'''
assert old in s; s=s.replace(old,new)
open(p,'w').write(s)
EOF

